package server

import (
	"net/http"
	"database/sql"
	"context"
	"time"
)

type Server struct {
	db *sql.DB
	cache Cache
	logger Logger
	metrics Metrics
}

func NewServer(cfg Config) *Server {
	return &Server{
		db: connectDB(cfg.Database),
		cache: newRedisCache(cfg.Cache),
		logger: newLogger(cfg.LogLevel),
		metrics: newMetrics(cfg.Metrics),
	}
}

func (s *Server) Start(ctx context.Context) error {
	srv := &http.Server{Addr: cfg.Addr, Handler: s.routes()}
	return srv.ListenAndServe()
}

package db

import (
	"database/sql"
	"context"
	"fmt"
	"time"
)

type DB struct {
	conn *sql.DB
	pool *Pool
}

func Connect(cfg DatabaseConfig) (*DB, error) {
	dsn := fmt.Sprintf("host=%s port=%d dbname=%s sslmode=require", cfg.Host, cfg.Port, cfg.Name)
	conn, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, fmt.Errorf("connect: %w", err)
	}
	conn.SetMaxOpenConns(cfg.PoolSize)
	conn.SetMaxIdleConns(cfg.MaxIdle)
	conn.SetConnMaxLifetime(cfg.Timeout)
	return &DB{conn: conn}, nil
}
